package com.quincaisoft.inventory.application;
import com.quincaisoft.inventory.api.*;import com.quincaisoft.inventory.infrastructure.*;import com.quincaisoft.catalog.api.CatalogService;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.function.Supplier;
@Service
public class DefaultInventoryWorkflows implements InventoryWorkflows {
 private final EntityManager em;private final ScopedTransactions tx;private final StockService stock;private final com.quincaisoft.finance.api.FinanceService finance;private final CatalogService catalog;private final JsonMapper json=JsonMapper.builder().build();
 public DefaultInventoryWorkflows(EntityManager em,ScopedTransactions tx,StockService stock,CatalogService catalog,com.quincaisoft.finance.api.FinanceService finance){this.em=em;this.tx=tx;this.stock=stock;this.catalog=catalog;this.finance=finance;}
 public List<Warehouse> warehouses(){return tx.execute(()->{var s=TenantContext.current();return em.createNativeQuery("select id,name,active,lock_version from warehouse where tenant_id=:t and company_id=:c and branch_id=:b order by name,id").setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).getResultStream().map(row->{Object[] a=(Object[])row;return new Warehouse((UUID)a[0],(String)a[1],(Boolean)a[2],((Number)a[3]).longValue());}).toList();});}
 @Override
 public long lowStockCount() {
  return tx.execute(() -> {
   var scope = TenantContext.current();
   return ((Number) em.createNativeQuery("""
       select count(*) from catalog_product p
       left join (
           select product_id,
                  sum(quantity_milli - reserved_milli - allocated_milli - quarantined_milli) as available
           from stock_balance
           where tenant_id = :tenant and company_id = :company and branch_id = :branch
           group by product_id
       ) stock on stock.product_id = p.id
       where p.tenant_id = :tenant and p.company_id = :company
         and p.active and p.track_stock and p.reorder_level_milli > 0
         and coalesce(stock.available, 0) < p.reorder_level_milli
       """)
       .setParameter("tenant", scope.tenantId())
       .setParameter("company", scope.companyId())
       .setParameter("branch", scope.branchId())
       .getSingleResult()).longValue();
  });
 }
 public List<Balance> balances(UUID warehouseId){return tx.execute(()->{stock.requireWarehouse(warehouseId);var s=TenantContext.current();return em.createQuery("select b from StockBalance b where b.tenantId=:t and b.companyId=:c and b.branchId=:b and b.warehouseId=:w order by b.productId",StockBalance.class).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("w",warehouseId).getResultList().stream().map(b->new Balance(b.warehouseId,b.productId,b.quantityMilli,b.reservedMilli,b.allocatedMilli,b.valueXaf,b.version,b.quarantinedMilli,b.available())).toList();});}
 public List<Transfer> transfers(){return tx.execute(()->{var s=TenantContext.current();return em.createQuery("select t from TransferEntity t where t.tenantId=:t and t.companyId=:c and t.branchId=:b order by t.createdAt desc",TransferEntity.class).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setMaxResults(200).getResultList().stream().map(this::view).toList();});}
 public Transfer get(UUID id){return tx.execute(()->view(find(id)));}
 private TransferEntity find(UUID id){var s=TenantContext.current();var r=em.find(TransferEntity.class,new TransferEntity.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null||!r.branchId.equals(s.branchId()))throw new NoSuchElementException("Transfer not found");return r;}
 private Transfer view(TransferEntity r){return new Transfer(r.id,r.originWarehouse,r.destinationWarehouse,r.productId,Long.toString(r.quantityMilli),Long.toString(r.receivedMilli),Long.toString(r.valueXaf),Long.toString(r.receivedValueXaf),r.status,Long.toString(r.version));}
 public Transfer draft(Draft c){if(c==null||c.operationId()==null||c.businessDate()==null||c.originWarehouse()==null||c.destinationWarehouse()==null||c.originWarehouse().equals(c.destinationWarehouse()))throw new IllegalArgumentException("Operation, date and distinct warehouses required");long qty=quantity(c.quantityMilli());reason(c.reason());return tx.execute(()->once(c.operationId(),"TRANSFER_DRAFT|"+c,()->{stock.requireWarehouse(c.originWarehouse());stock.requireWarehouse(c.destinationWarehouse());if(!catalog.get(c.productId()).active())throw new IllegalArgumentException("Product inactive");var s=TenantContext.current();var r=new TransferEntity();r.id=UUID.randomUUID();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.originWarehouse=c.originWarehouse();r.destinationWarehouse=c.destinationWarehouse();r.productId=c.productId();r.quantityMilli=qty;r.businessDate=c.businessDate();r.status="DRAFT";r.reason=c.reason();r.createdBy=s.actorId();r.createdAt=Instant.now();em.persist(r);em.flush();return r;}));}
 public Transfer approve(UUID id,Command c){return command(id,c,"APPROVE",r->{if(!r.status.equals("DRAFT"))throw new IllegalStateException("Only draft transfers can be approved");if(r.createdBy.equals(TenantContext.current().actorId()))throw new IllegalStateException("A different actor must approve");r.approvedBy=TenantContext.current().actorId();r.status="APPROVED";});}
 public Transfer dispatch(UUID id,Command c){return command(id,c,"DISPATCH",r->{if(!r.status.equals("APPROVED"))throw new IllegalStateException("Independent approval required before dispatch");openPeriod(r);var issue=stock.issue(r.originWarehouse,r.productId,r.quantityMilli,derived(c.operationId(),"dispatch"),c.reason());r.valueXaf=issue.valueXaf();r.status="IN_TRANSIT";});}
 public Transfer receive(UUID id,Command c){long qty=quantity(c.quantityMilli());return command(id,c,"RECEIVE",r->{if(!Set.of("IN_TRANSIT","PARTIALLY_RECEIVED").contains(r.status))throw new IllegalStateException("Transfer is not in transit");openPeriod(r);long left=Math.subtractExact(r.quantityMilli,r.receivedMilli);if(qty>left)throw new IllegalArgumentException("Receipt exceeds transit remainder");long value=StockCost.exactIssue(Math.subtractExact(r.valueXaf,r.receivedValueXaf),qty,left);stock.receive(r.destinationWarehouse,r.productId,qty,value,derived(c.operationId(),"receive"),c.reason());r.receivedMilli=Math.addExact(r.receivedMilli,qty);r.receivedValueXaf=Math.addExact(r.receivedValueXaf,value);r.status=r.receivedMilli==r.quantityMilli?"RECEIVED":"PARTIALLY_RECEIVED";});}
 private Transfer command(UUID id,Command c,String verb,java.util.function.Consumer<TransferEntity> work){if(c==null||c.operationId()==null||c.version()==null||!c.version().matches("0|[1-9][0-9]*"))throw new IllegalArgumentException("Operation and version required");reason(c.reason());return tx.execute(()->once(c.operationId(),verb+"|"+id+"|"+c,()->{var r=find(id);if(r.version!=Long.parseLong(c.version()))throw new RevisionConflict("Transfer changed");work.accept(r);em.flush();return r;}));}
 private void openPeriod(TransferEntity r){finance.requireOpenPeriod(r.businessDate);}
 private Transfer once(UUID op,String material,Supplier<TransferEntity> action){var s=TenantContext.current();String digest=hash(material);em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",s.tenantId()+":"+op).getSingleResult();var prior=em.createNativeQuery("select request_hash,response_json::text,company_id,branch_id,actor_id,source_type,status from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",op).getResultList();if(!prior.isEmpty()){Object[] row=(Object[])prior.getFirst();if(!digest.equals(row[0])||!s.companyId().equals(row[2])||!s.branchId().equals(row[3])||!s.actorId().equals(row[4])||!"TRANSFER".equals(row[5])||!"ACCEPTED".equals(row[6]))throw new IllegalStateException("Operation belongs to another request, scope or actor");if(row[1]==null)throw new IllegalStateException("Committed response expired; reconcile original transfer");return json.readValue((String)row[1],Transfer.class);}var r=action.get();var result=view(r);em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json)values(:t,:o,:c,:b,:h,'TRANSFER',:id,cast(:body as jsonb))").setParameter("t",s.tenantId()).setParameter("o",op).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",digest).setParameter("id",r.id).setParameter("body",json.writeValueAsString(result)).executeUpdate();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload) values(:t,:event,:c,:b,:o,'TransferChanged.v1','inventory_transfer',:id,cast(:body as jsonb))").setParameter("t",s.tenantId()).setParameter("event",UUID.randomUUID()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",op).setParameter("id",r.id).setParameter("body",json.writeValueAsString(result)).executeUpdate();return result;}
 private static long quantity(String v){if(v==null||!v.matches("[1-9][0-9]*"))throw new IllegalArgumentException("Positive integral milli quantity required");return Long.parseLong(v);}
 private static void reason(String v){if(v==null||v.isBlank()||v.length()>2000)throw new IllegalArgumentException("Reason required");}
 private static UUID derived(UUID op,String action){return UUID.nameUUIDFromBytes((op+":"+action).getBytes(StandardCharsets.UTF_8));}
 private static String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
